{"name": "Entity", "start_line": 12, "end_line": 31, "docstring": "Anything with a stable identity; equality and hashing derive from it.", "bases": ["ABC"], "decorators": [], "methods": ["    @abstractmethod
    def identity(self) -> str:
        """Return the unique key for this entity."""", "    def __eq__(self, other: object) -> bool:
        """Compare identity for entities of the same concrete type."""
        if type(self) is not type(other):
            return NotImplemented
        return self.identity() == other.identity()", "    def __hash__(self) -> int:
        """Hash by the concrete type name and identity."""
        return hash((type(self).__name__, self.identity()))", "    def __repr__(self) -> str:
