        return f"{type(self).__name__}({self.identity()!r})""], "class_code": []}

{"name": "PricingStrategy", "start_line": 34, "end_line": 55, "docstring": "Computes an order total from line items.", "bases": ["ABC"], "decorators": [], "methods": ["    @abstractmethod
    def price(self, items: Sequence["LineItem"]) -> "Money":
        """Return the total for the given items."""", "    def __call__(self, items: Sequence["LineItem"]) -> "Money":
        """Convenience alias for :meth:`price`."""
        return self.price(items)", "    @staticmethod
    def _sum_subtotals(items: Sequence["LineItem"]) -> "Money":
        """Sum the subtotal of each item, returning a zero Money for empty input."""
        from .models import Money

        if len(items) == 0:
            return Money(0)
        total = Money(0)
        for item in items:
            total = total + item.subtotal
        return total"], "class_code": []}

