{"name": "Category", "start_line": 8, "end_line": 34, "docstring": "Product categories within the warehouse catalogue.", "bases": ["Enum"], "decorators": [], "methods": ["    @classmethod
    def from_label(cls, label: str) -> "Category":
        """Resolve a category from its lowercase label string.

        Raises:
            TypeError: if ``label`` is not a string.
            ValueError: if no member has a matching value.
        """
        if not isinstance(label, str):
            raise TypeError("category label must be str")
        key = label.strip().lower()
        for member in cls:
            if member.value == key:
                return member
        raise ValueError(f"unknown category: {label!r}")", "    def __str__(self) -> str:
        """Return the category's value as its string form."""
        return self.value"], "class_code": ["    ELECTRONICS = "electronics"", "    GROCERY = "grocery"", "    APPAREL = "apparel"", "    HARDWARE = "hardware""]}

{"name": "EventBus", "start_line": 11, "end_line": 54, "docstring": "Synchronous publish/subscribe keyed by :class:`EventType`.", "bases": [], "decorators": [], "methods": ["    def __init__(self) -> None:
        """Initialise an empty handler registry."""
        self._handlers: Dict[EventType, List[Callable[..., None]]] = {}", "    def subscribe(self, event_type: EventType, handler: Callable[..., None]) -> None:
        """Register ``handler`` to be called when ``event_type`` is published."""
        if not isinstance(event_type, EventType):
            raise TypeError("event_type must be EventType")
        if not callable(handler):
            raise TypeError("handler must be callable")
        self._handlers.setdefault(event_type, []).append(handler)", "    def unsubscribe(self, event_type: EventType, handler: Callable[..., None]) -> bool:
        """Remove ``handler`` from ``event_type``; return whether it was present."""
        handlers = self._handlers.get(event_type, [])
        if handler not in handlers:
            return False
        handlers.remove(handler)
        return True", "    def publish(self, event_type: EventType, payload: Mapping[str, object]) -> int:
        """Invoke every handler subscribed to ``event_type`` with ``payload``.

        Returns the number of handlers invoked.
        """
        if not isinstance(event_type, EventType):
            raise TypeError("event_type must be EventType")
        if not isinstance(payload, Mapping):
            raise TypeError("payload must be a Mapping")
        count = 0
        for handler in list(self._handlers.get(event_type, [])):
            handler(payload)
            count += 1
        return count", "    def __len__(self) -> int:
        """Return the total number of registered handlers across all event types."""
        return sum(len(handlers) for handlers in self._handlers.values())", "    def __contains__(self, event_type: object) -> bool:
        pass"], "class_code": []}

{"name": "ReservationContext", "start_line": 84, "end_line": 121, "docstring": "Context manager for a reservation; releases on exit unless committed.", "bases": [], "decorators": [], "methods": ["    def __init__(self, ledger: InventoryLedger, sku: str, quantity: int) -> None:
        """Create a held reservation for ``quantity`` of ``sku`` in ``ledger``."""
        self._ledger = ledger
        self._sku = sku
        self._quantity = quantity
        self._state = "held"", "    @property
    def state(self) -> str:
        """Return the current reservation state."""
        return self._state", "    def __enter__(self) -> ReservationContext:
        """Enter the context; raises if the reservation is not in the held state."""
        if self._state != "held":
            raise InvalidTransitionError(self._state, "held")
        return self", "    def __exit__(self, exc_type: object, exc: object, tb: object) -> bool:
        """Release the reservation on exit unless it was committed."""
        if self._state == "held":
            self._ledger.release(self._sku, self._quantity)
            self._state = "released"
        return False", "    def commit(self) -> None:
        """Commit the reservation, decrementing stock; raises if not held."""
        if self._state != "held":
            raise InvalidTransitionError(self._state, "committed")
        self._ledger.commit(self._sku, self._quantity)
        self._state = "committed"", "    def __repr__(self) -> str:
        """Return a developer-friendly representation."""
        return f"ReservationContext({self._sku!r}, {self._quantity}, {self._state!r})""], "class_code": []}

