        """Return the number of recorded lines."""
        return len(self._lines)", "    def __bool__(self) -> bool:
        """Return True when at least one line has been recorded."""
        return len(self) > 0"], "class_code": []}

{"name": "OrderLog", "start_line": 167, "end_line": 196, "docstring": "Ordered, deduplicated record of orders; iterable.", "bases": [], "decorators": [], "methods": ["    def __init__(self) -> None:
        """Create an empty order log."""
