        self._orders.append(order)", "    def by_status(self, status: OrderStatus) -> Iterator[Order]:
        pass", "    def __getitem__(self, index: int) -> Order:
        """Return the order at ``index``."""
        return self._orders[index]", "    def __len__(self) -> int:
        """Return the number of logged orders."""
