{"name": "FlatPricing", "start_line": 12, "end_line": 34, "docstring": "Sum of subtotals plus flat tax in basis points.", "bases": ["PricingStrategy"], "decorators": [], "methods": ["    def __init__(self, tax_bps: int = 0) -> None:
        """Create a pricing strategy with a tax rate in ``tax_bps`` basis points."""
        if isinstance(tax_bps, bool) or not isinstance(tax_bps, int):
            raise TypeError("tax_bps must be int")
        if tax_bps < 0 or tax_bps > 10000:
            raise ValueError("tax_bps must be 0..10000")
        self._tax_bps = tax_bps", "    @property
    def tax_bps(self) -> int:
        """Return the tax rate in basis points."""
        return self._tax_bps", "    def price(self, items: Sequence[LineItem]) -> Money:
        """Return the subtotal plus the configured flat tax."""
        subtotal = self._sum_subtotals(items)
        if self._tax_bps == 0:
            return subtotal
        tax = Money(subtotal.cents * self._tax_bps // 10000)
        return subtotal + tax"], "class_code": []}

{"name": "BulkDiscountPricing", "start_line": 37, "end_line": 68, "docstring": "Wraps another strategy; applies a percent discount when total quantity meets a threshold.", "bases": ["PricingStrategy"], "decorators": [], "methods": ["    def __init__(self, base: PricingStrategy, threshold: int, percent_off: int) -> None:
